WITH totals AS (SELECT payroll_month,department,SUM(payroll_cost) payroll_cost,COUNT(DISTINCT emp_id) employees,SUM(payroll_cost)/COUNT(DISTINCT emp_id) cost_per_employee FROM warehouse_monthly_employee GROUP BY 1,2) SELECT *,cost_per_employee/NULLIF(LAG(cost_per_employee) OVER(PARTITION BY department ORDER BY payroll_month),0)-1 AS mom_change_pct FROM totals ORDER BY department,payroll_month;
